bootforge/async-js/foundations/callbacks.solution:
function promisify(fn) {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (err, result) => {
        if (err) reject(err);
        else resolve(result);
      });
    });
}

export function promisifyAll(obj) {
  const out = {};
  for (const key of Object.keys(obj)) {
    const value = obj[key];
    out[key] = typeof value === 'function' ? promisify(value) : value;
  }
  return out;
}

