export function sequentialChain(values, fn) {
  const results = [];
  let chain = Promise.resolve();
  for (const value of values) {
    chain = chain
      .then(() => fn(value))
      .then((result) => {
        results.push(result);
      });
  }
  return chain.then(() => results);
}

