const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retryWithDelay(fn, attempts, ms) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    if (i > 0) await delay(ms);
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

